using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculateShippingFeeQuery(
    int PayableTotalCents,
    LoyaltyTier LoyaltyTier,
    bool Express = false);

public sealed class CalculateShippingFee
{
    public int Handle(CalculateShippingFeeQuery query) => -1;
}

using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record QuoteCheckoutQuery(
    int SubtotalCents,
    LoyaltyTier LoyaltyTier,
    string? PromoCode,
    bool Express);

public sealed record CheckoutQuote(int PayableCents, int ShippingCents, int TotalCents);

public sealed class QuoteCheckout
{
    public CheckoutQuote Handle(QuoteCheckoutQuery query) => new(-1, -1, -1);
}

using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public sealed class CalculateLoyaltyDiscountAcceptanceTests
{
    private static void AssertQuote(int subtotal, LoyaltyTier tier, string? code, int discount, int? total)
    {
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(subtotal, tier, code));

        Assert.Equal(discount, quote.DiscountCents);
        if (total is not null)
        {
            Assert.Equal(total, quote.TotalCents);
        }
    }

    // Member receives the loyalty discount of their tier
    [Theory]
    [InlineData(10000, LoyaltyTier.Bronze, null, 500, 9500)]
    [InlineData(10000, LoyaltyTier.Silver, null, 1000, 9000)]
    [InlineData(10000, LoyaltyTier.Gold, null, 1500, 8500)]
    public void S1_MemberReceivesTheLoyaltyDiscountOfTheirTier(int subtotal, LoyaltyTier tier, string? code, int discount, int? total) =>
        AssertQuote(subtotal, tier, code, discount, total);

    // The loyalty discount never exceeds 20.00 EUR
    [Theory]
    [InlineData(20000, LoyaltyTier.Gold, null, 2000, 18000)]
    [InlineData(30000, LoyaltyTier.Silver, null, 2000, 28000)]
    [InlineData(12000, LoyaltyTier.Gold, null, 1800, 10200)]
    public void S2_LoyaltyDiscountNeverExceedsTwentyEuros(int subtotal, LoyaltyTier tier, string? code, int discount, int? total) =>
        AssertQuote(subtotal, tier, code, discount, total);

    // No loyalty discount under a 30.00 EUR subtotal
    [Theory]
    [InlineData(2999, LoyaltyTier.Gold, null, 0, 2999)]
    [InlineData(3000, LoyaltyTier.Gold, null, 450, 2550)]
    public void S3_NoLoyaltyDiscountUnderThirtyEuroSubtotal(int subtotal, LoyaltyTier tier, string? code, int discount, int? total) =>
        AssertQuote(subtotal, tier, code, discount, total);

    // The WELCOME5 promo code takes 5.00 EUR off after the loyalty discount
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, "WELCOME5", 1500, 8500)]
    [InlineData(2000, LoyaltyTier.Bronze, "WELCOME5", 500, 1500)]
    public void S4_Welcome5TakesFiveEurosOffAfterLoyaltyDiscount(int subtotal, LoyaltyTier tier, string? code, int discount, int? total) =>
        AssertQuote(subtotal, tier, code, discount, total);

    // The cap applies to the loyalty discount only, never to WELCOME5
    [Theory]
    [InlineData(20000, LoyaltyTier.Gold, "WELCOME5", 2500, 17500)]
    [InlineData(30000, LoyaltyTier.Silver, "WELCOME5", 2500, 27500)]
    public void S5_CapAppliesToLoyaltyDiscountOnlyNeverToWelcome5(int subtotal, LoyaltyTier tier, string? code, int discount, int? total) =>
        AssertQuote(subtotal, tier, code, discount, total);

    // Promo codes ignore case
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, "welcome5", 1500, null)]
    [InlineData(10000, LoyaltyTier.Silver, "Welcome5", 1500, null)]
    public void S6_PromoCodesIgnoreCase(int subtotal, LoyaltyTier tier, string? code, int discount, int? total) =>
        AssertQuote(subtotal, tier, code, discount, total);

    // The SUMMER10 promo code takes 10 % off what is left, at most 15.00 EUR
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, "SUMMER10", 1900, 8100)]
    [InlineData(30000, LoyaltyTier.Bronze, "SUMMER10", 3000, 27000)]
    [InlineData(2000, LoyaltyTier.Gold, "SUMMER10", 200, 1800)]
    public void S7_Summer10TakesTenPercentOffWhatIsLeftAtMostFifteenEuros(int subtotal, LoyaltyTier tier, string? code, int discount, int? total) =>
        AssertQuote(subtotal, tier, code, discount, total);

    // An unknown promo code is ignored
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, "SPRING", 1000, 9000)]
    public void S8_UnknownPromoCodeIsIgnored(int subtotal, LoyaltyTier tier, string? code, int discount, int? total) =>
        AssertQuote(subtotal, tier, code, discount, total);

    // Platinum members receive a 20 % loyalty discount
    [Theory]
    [InlineData(10000, LoyaltyTier.Platinum, null, 2000, 8000)]
    [InlineData(5000, LoyaltyTier.Platinum, null, 1000, 4000)]
    [InlineData(20000, LoyaltyTier.Platinum, null, 2000, 18000)]
    public void S9_PlatinumMembersReceiveTwentyPercentLoyaltyDiscount(int subtotal, LoyaltyTier tier, string? code, int discount, int? total) =>
        AssertQuote(subtotal, tier, code, discount, total);

    // The discount never exceeds the subtotal
    [Theory]
    [InlineData(400, LoyaltyTier.Bronze, "WELCOME5", 400, 0)]
    [InlineData(300, LoyaltyTier.Gold, "WELCOME5", 300, 0)]
    public void S10_DiscountNeverExceedsTheSubtotal(int subtotal, LoyaltyTier tier, string? code, int discount, int? total) =>
        AssertQuote(subtotal, tier, code, discount, total);
}

using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public sealed class CalculateShippingFeeAcceptanceTests
{
    // Standard shipping is free from 50.00 EUR payable
    [Theory]
    [InlineData(4999, LoyaltyTier.Bronze, 490)]
    [InlineData(5000, LoyaltyTier.Bronze, 0)]
    [InlineData(4999, LoyaltyTier.Silver, 490)]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(int payable, LoyaltyTier tier, int fee) =>
        Assert.Equal(fee, new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payable, tier, false)));

    // Gold and Platinum members never pay standard shipping
    [Theory]
    [InlineData(1000, LoyaltyTier.Gold, 0)]
    [InlineData(1000, LoyaltyTier.Platinum, 0)]
    public void S12_GoldAndPlatinumMembersNeverPayStandardShipping(int payable, LoyaltyTier tier, int fee) =>
        Assert.Equal(fee, new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payable, tier, false)));

    // Express shipping costs 9.90 EUR, free for Platinum members only
    [Theory]
    [InlineData(10000, LoyaltyTier.Bronze, 990)]
    [InlineData(1000, LoyaltyTier.Gold, 990)]
    [InlineData(1000, LoyaltyTier.Platinum, 0)]
    public void S13_ExpressShippingCostsNinePointNinetyFreeForPlatinumOnly(int payable, LoyaltyTier tier, int fee) =>
        Assert.Equal(fee, new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payable, tier, true)));
}

using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public sealed class QuoteCheckoutAcceptanceTests
{
    // The checkout quote adds shipping to the payable total
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, "WELCOME5", false, 8500, 0, 8500)]
    [InlineData(5000, LoyaltyTier.Bronze, null, false, 4750, 490, 5240)]
    [InlineData(20000, LoyaltyTier.Platinum, "SUMMER10", true, 16500, 0, 16500)]
    [InlineData(2000, LoyaltyTier.Gold, null, true, 2000, 990, 2990)]
    public void S14_CheckoutQuoteAddsShippingToPayableTotal(
        int subtotal, LoyaltyTier tier, string? code, bool express, int payable, int fee, int total)
    {
        var quote = new QuoteCheckout().Handle(new QuoteCheckoutQuery(subtotal, tier, code, express));

        Assert.Equal(payable, quote.PayableCents);
        Assert.Equal(fee, quote.ShippingCents);
        Assert.Equal(total, quote.TotalCents);
    }
}

